package com.researchdesk.research;
import com.fasterxml.jackson.databind.*;
import java.net.*;import java.net.http.*;import java.nio.file.*;import java.util.*;
import org.junit.jupiter.api.*;import static org.assertj.core.api.Assertions.*;
/** Real HTTP and PostgreSQL fixtures; only the isolated researchdesk-generation Compose project. */
class RunRecoveryIT {
 final ObjectMapper json=new ObjectMapper();final HttpClient http=HttpClient.newHttpClient();final String base=System.getenv().getOrDefault("ACCEPTANCE_URL","http://localhost:18083");
 String cookie,csrf,project,owner,conversation; final List<String> users=new ArrayList<>();
 String sql(String sql)throws Exception{var p=new ProcessBuilder("docker","compose","-p","researchdesk-generation","-f",Path.of(System.getProperty("user.dir"),"../../infra/compose.yaml").normalize().toString(),"exec","-T","postgres","psql","-U","researchdesk","-d","researchdesk","-At","-v","ON_ERROR_STOP=1","-f","-").redirectErrorStream(true).start();p.getOutputStream().write(sql.getBytes(java.nio.charset.StandardCharsets.UTF_8));p.getOutputStream().close();String out=new String(p.getInputStream().readAllBytes());assertThat(p.waitFor()).as(out).isZero();return out.strip();}
 HttpResponse<String> request(String method,String path,String body)throws Exception{var b=HttpRequest.newBuilder(URI.create(base+path)).header("Content-Type","application/json");if(cookie!=null)b.header("Cookie",cookie);if(csrf!=null)b.header("X-CSRF-Token",csrf);return http.send(b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
 @BeforeEach void fixture()throws Exception{String email="run-"+UUID.randomUUID()+"@test.local";users.add(email);var r=request("POST","/api/auth/register","{\"email\":\""+email+"\",\"password\":\"PasswordTest123!\"}");assertThat(r.statusCode()).isEqualTo(201);cookie=r.headers().firstValue("set-cookie").orElseThrow().split(";",2)[0];csrf=json.readTree(r.body()).get("csrfToken").asText();project=json.readTree(request("POST","/api/projects","{\"name\":\"run recovery\"}").body()).get("id").asText();owner=sql("SELECT id FROM business.users WHERE email='"+email+"'");conversation=UUID.randomUUID().toString();sql("INSERT INTO business.conversations(id,project_id) VALUES ('"+conversation+"','"+project+"')");}
 @AfterEach void cleanup()throws Exception{for(String email:users)sql("DELETE FROM business.users WHERE email='"+email+"'; DELETE FROM business.auth_throttles WHERE key='email:"+email+"'");}
 String run(String state,int seq)throws Exception{String id=UUID.randomUUID().toString();sql("INSERT INTO business.generation_runs(id,project_id,owner_id,conversation_id,kind,state,prompt,document_version_ids,history,mode,last_seq,deadline) VALUES ('"+id+"','"+project+"','"+owner+"','"+conversation+"','ANSWER','"+state+"','question','[]','[]','DEMO',"+seq+",now()+interval '60 seconds')");return id;}
 @Test void cancelIsDurableIdempotentAndTerminal()throws Exception{String id=run("RUNNING",0);var first=request("POST","/api/runs/"+id+"/cancel",null);assertThat(first.statusCode()).isEqualTo(200);assertThat(json.readTree(first.body()).get("state").asText()).isEqualTo("CANCELLED");assertThat(json.readTree(request("POST","/api/runs/"+id+"/cancel",null).body()).get("lastSeq").asInt()).isEqualTo(1);assertThat(sql("SELECT count(*) FROM business.run_events WHERE run_id='"+id+"'")).isEqualTo("1");}
 @Test void resumesOnlyMissingEventsAndExpiredWindowFallsBackToSnapshot()throws Exception{String id=run("COMPLETED",3);sql("INSERT INTO business.run_events(run_id,seq,type,payload) VALUES ('"+id+"',1,'started','{\"kind\":\"ANSWER\"}'),('"+id+"',2,'delta','{\"text\":\"hello\"}'),('"+id+"',3,'completed','{\"state\":\"COMPLETED\"}')");var response=http.send(HttpRequest.newBuilder(URI.create(base+"/api/runs/"+id+"/events")).header("Cookie",cookie).header("Last-Event-ID","1").GET().build(),HttpResponse.BodyHandlers.ofString());assertThat(response.statusCode()).isEqualTo(200);assertThat(response.body()).contains("id:2","id:3").doesNotContain("id:1");sql("UPDATE business.run_events SET created_at=now()-interval '25 hours' WHERE run_id='"+id+"'");var expired=http.send(HttpRequest.newBuilder(URI.create(base+"/api/runs/"+id+"/events")).header("Cookie",cookie).header("Accept","text/event-stream").GET().build(),HttpResponse.BodyHandlers.ofString());assertThat(expired.statusCode()).isEqualTo(410);assertThat(json.readTree(expired.body()).get("code").asText()).isEqualTo("EVENT_WINDOW_EXPIRED");assertThat(request("GET","/api/runs/"+id,null).statusCode()).isEqualTo(200);}
 @Test void sseMalformedCursorReturnsJsonEvenWhenClientAcceptsOnlyEventStream()throws Exception{String id=run("COMPLETED",0);var r=http.send(HttpRequest.newBuilder(URI.create(base+"/api/runs/"+id+"/events")).header("Cookie",cookie).header("Accept","text/event-stream").header("Last-Event-ID","garbage").GET().build(),HttpResponse.BodyHandlers.ofString());assertThat(r.statusCode()).isEqualTo(400);assertThat(r.headers().firstValue("content-type").orElse("")).startsWith("application/json");assertThat(json.readTree(r.body()).get("code").asText()).isEqualTo("INVALID_EVENT_CURSOR");}
 @Test void activeQuotaIsPerUserAndForeignScopeFails()throws Exception{run("RUNNING",0);run("RUNNING",0);var r=request("POST","/api/runs","{\"kind\":\"ANSWER\",\"projectId\":\""+project+"\",\"documentVersionIds\":[],\"prompt\":\"question\"}");assertThat(r.statusCode()).isEqualTo(429);assertThat(json.readTree(r.body()).get("code").asText()).isEqualTo("RUN_CONCURRENCY_LIMIT");}
 @Test void foreignOwnerCannotReadSubscribeOrCancel()throws Exception{String id=run("RUNNING",0);String previousCookie=cookie;cookie=null;csrf=null;String email="run-"+UUID.randomUUID()+"@test.local";users.add(email);var r=request("POST","/api/auth/register","{\"email\":\""+email+"\",\"password\":\"PasswordTest123!\"}");cookie=r.headers().firstValue("set-cookie").orElseThrow().split(";",2)[0];csrf=json.readTree(r.body()).get("csrfToken").asText();assertThat(request("GET","/api/runs/"+id,null).statusCode()).isEqualTo(404);assertThat(request("GET","/api/runs/"+id+"/events",null).statusCode()).isEqualTo(404);assertThat(request("POST","/api/runs/"+id+"/cancel",null).statusCode()).isEqualTo(404);}

 @Test void actualForeignConversationCannotBeAttachedToOwnedProject()throws Exception{
  String foreignOwner=UUID.randomUUID().toString(),foreignProject=UUID.randomUUID().toString(),foreignConversation=UUID.randomUUID().toString(),email="foreign-"+UUID.randomUUID()+"@test.local";users.add(email);
  sql("INSERT INTO business.users(id,email,password_hash) VALUES ('"+foreignOwner+"','"+email+"','unused'); INSERT INTO business.projects(id,owner_id,name) VALUES ('"+foreignProject+"','"+foreignOwner+"','Foreign project'); INSERT INTO business.conversations(id,project_id) VALUES ('"+foreignConversation+"','"+foreignProject+"')");
  String body=json.writeValueAsString(Map.of("kind","ANSWER","projectId",project,"conversationId",foreignConversation,"documentVersionIds",List.of(),"prompt","question"));
  var response=request("POST","/api/runs",body);assertThat(response.statusCode()).isEqualTo(404);assertThat(json.readTree(response.body()).get("code").asText()).isEqualTo("RUN_NOT_FOUND");
 }
 @Test void expiredRunningAttemptFailsWithoutRestartingModel()throws Exception{
  String id=run("RUNNING",1);sql("UPDATE business.generation_runs SET deadline=now()-interval '1 second' WHERE id='"+id+"'");
  long end=System.nanoTime()+10_000_000_000L;
  while(System.nanoTime()<end){var snapshot=json.readTree(request("GET","/api/runs/"+id,null).body());if(snapshot.get("state").asText().equals("FAILED")){assertThat(snapshot.get("error").get("code").asText()).isEqualTo("RUN_DEADLINE_EXCEEDED");assertThat(sql("SELECT count(*) FROM business.run_events WHERE run_id='"+id+"' AND type='started'")).isEqualTo("0");return;}Thread.sleep(100);}
  throw new AssertionError("Expired attempt did not fail");
 }
}
